-- Repartidor de misiones
lang["#MISSION_GIVER_LOGAN"] = "Teniente Logan"
lang["#MISSION_GIVER_LOGAN_SUBTITLE"] = "República de Nueva California"
lang["#MISSION_GIVER_LOGAN_NEW"] = "¿Nuevo por aquí? Habla con el Mayor Redman y ayuda en el pueblo antes de volver a verme. Entonces podremos hablar de trabajo. Necesito a alguien que pueda demostrar su lealtad a la república."
lang["#MISSION_GIVER_LOGAN_GREET_N100"] = "Sal de mi vista."
lang["#MISSION_GIVER_LOGAN_800"] = "$playername, tengo más trabajos para ti. Sigue demostrando tu valía a la república."
lang["#MISSION_GIVER_LOGAN_1000"] = "$playername, bienvenido de nuevo. Tengo el trabajo perfecto para alguien leal a la república como tú."
lang["#MISSION_GIVER_LOGAN_GREET_FINISHED"] = "$playername, es un honor verte. Sin embargo, no tengo nada más para ti que hacer. Eres un héroe para la república."

-- Misiones
lang["#MISSION_LOGAN_LINEINTHESANDPT1"] = "Línea en la Arena: Tribu de los 80s"
lang["#MISSION_LOGAN_LINEINTHESANDPT1_DESC"] = "$playername, tengo varias tareas que requieren a alguien en quien se pueda confiar sin duda. Si estás interesado, puedes empezar demostrando tu valía eliminando a los bandidos cercanos."
lang["#MISSION_LOGAN_LINEINTHESANDPT1_HINT"] = "**ADVERTENCIA** Completar esta misión dañará irreversiblemente tu reputación con los 80s."
lang["#MISSION_LOGAN_LINEINTHESANDPT1_COMPLETE"] = "¡Buen trabajo $playername! La zona que rodea el pueblo será mucho más segura gracias a ti."

lang["#MISSION_LOGAN_GEARREQUISITION"] = "Requisa de Equipo"
lang["#MISSION_LOGAN_GEARREQUISITION_DESC"] = "Hola $playername, tras tu reciente contribución he presentado una solicitud para que recibas un conjunto oficial de armadura. Solo necesito algunas cosas de tu parte y será toda tuya."
lang["#MISSION_LOGAN_GEARREQUISITION_HINT"] = "Obtén los materiales de fabricación y los vales requeridos. La mayoría de estos objetos se pueden obtener luchando contra enemigos o saqueando. Algunos comerciantes pueden tener los objetos requeridos."
lang["#MISSION_LOGAN_GEARREQUISITION_COMPLETE"] = "Felicidades $playername, espero que continúes con tu gran trabajo."

lang["#MISSION_LOGAN_LINEINTHESANDPT2"] = "Línea en la Arena: Rockbiters"
lang["#MISSION_LOGAN_LINEINTHESANDPT2_DESC"] = "$playername, tras tu triunfo contra los Ochentas, tengo una tarea más difícil. Hay un grupo de bandidos cerca de los Rangers del Desierto en Yolla Bolly. No se les puede permitir prosperar, ve a Yolla Bolly y elimínalos."
lang["#MISSION_LOGAN_LINEINTHESANDPT2_HINT"] = "**ADVERTENCIA** Completar esta misión dañará irreversiblemente tu reputación con los Rockbiters."
lang["#MISSION_LOGAN_LINEINTHESANDPT2_COMPLETE"] = "Los Rangers del Desierto y los Supervivientes del Valle agradecerán enormemente tu trabajo, al igual que yo. Tengo un último grupo problemático que debe ser abordado antes de darte las tareas verdaderamente importantes."

lang["#MISSION_LOGAN_LINEINTHESANDPT3"] = "Línea en la Arena: Compañía Cipher"
lang["#MISSION_LOGAN_LINEINTHESANDPT3_DESC"] = "La Compañía Cipher ha sido durante mucho tiempo una espina en nuestro costado, traficando drogas y evadiendo impuestos. Sin mencionar que están en conflicto armado directo con nuestros aliados. $playername, ve y lisiar su organización en el Paso de la Montaña."
lang["#MISSION_LOGAN_LINEINTHESANDPT3_HINT"] = "**ADVERTENCIA** Completar esta misión dañará irreversiblemente tu reputación con la Compañía Cipher."
lang["#MISSION_LOGAN_LINEINTHESANDPT3_COMPLETE"] = "El Paso de la Montaña será mucho menos peligroso de transitar con las operaciones de la Compañía Cipher dañadas."

lang["#MISSION_LOGAN_REGIONPROTECTION"] = "Protección de la Región"
lang["#MISSION_LOGAN_REGIONPROTECTION_DESC"] = "Has trabajado duro para proteger la región circundante de las amenazas, no lo desperdicies dejando que esas amenazas se reconstruyan, $playername."
lang["#MISSION_LOGAN_REGIONPROTECTION_HINT"] = "Elimina a 1 jefe y 10 miembros de los 80s, los Rockbiters y la Compañía Cipher."
lang["#MISSION_LOGAN_REGIONPROTECTION_COMPLETE"] = "Trabajo increíble manteniendo la región segura, aquí tienes tu recompensa."

lang["#MISSION_LOGAN_OURBESTFRIENDS"] = "Nuestros Mejores Amigos"
lang["#MISSION_LOGAN_OURBESTFRIENDS_DESC"] = "Ahora que has demostrado tu valía, finalmente podemos hablar de negocios verdaderamente importantes. La expedición a las regiones del norte ha resultado bastante difícil, sin embargo, los Rangers del Desierto han establecido casas seguras. Recoge informes de ellos para obtener una evaluación real de las regiones circundantes."
lang["#MISSION_LOGAN_OURBESTFRIENDS_HINT"] = "Recoge el informe de estado del cuartel general de los Rangers del Desierto en Yolla Bolly."
lang["#MISSION_LOGAN_OURBESTFRIENDS_COMPLETE"] = "Incluso con tus contribuciones previas, la situación no pinta bien. Buen trabajo consiguiendo estos informes."
lang["#MISSION_LOGAN_OURBESTFRIENDS_ITEMNAME"] = "El Informe de Estado de las Regiones"

lang["#MISSION_LOGAN_RANGERSOLIDARITY"] = "Solidaridad con los Rangers"
lang["#MISSION_LOGAN_RANGERSOLIDARITY_DESC"] = "Los informes muestran que incluso en Yolla Bolly, las cosas son nefastas. Necesitamos que vayas a ayudar a los Rangers del Desierto a estabilizar la región primero."
lang["#MISSION_LOGAN_RANGERSOLIDARITY_HINT"] = "Elimina a estos enemigos en Yolla Bolly. Los Sanguinarios se pueden encontrar cerca y en el templo. Los Protectrones se pueden encontrar en la fábrica y en el silo. Los Rockbiters se pueden encontrar en las minas y en el túnel."
lang["#MISSION_LOGAN_RANGERSOLIDARITY_COMPLETE"] = "Yolla Bolly finalmente puede empezar a convertirse en un lugar más seguro gracias a ti. Con las regiones del sur estabilizadas, es hora de empezar a mirar hacia el norte."

lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT"] = "Apoyo a los Rangers"
lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT_DESC"] = "La casa segura de los Rangers del Desierto en las Tierras de Cenizas ha enviado informes sobre un gran ejército de mutantes en la región. Necesitamos reducir esos números."
lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT_HINT"] = "Elimina a 100 Supermutantes en las Tierras de Cenizas."
lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT_COMPLETE"] = "Buen trabajo lidiando con esos mutantes, sin embargo, los informes muestran que la región sigue siendo extremadamente hostil. Tengo otro trabajo para ti."

lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT"] = "Ayudando al Campamento Willow"
lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT_DESC"] = "El Campamento Willow en el Paso de la Montaña está bajo constante amenaza de un grupo de bandidos caníbales en constante crecimiento. Deben ser detenidos o todos los caminos hacia las regiones del norte quedarán bloqueados."
lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT_HINT"] = "Encuentra y elimina a 100 bandidos Ice Pick en el Paso de la Montaña."
lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT_COMPLETE"] = "Gracias a tu duro trabajo $playername, el paso permanecerá abierto. Aunque el peligro aún acecha en cada esquina."

lang["#MISSION_LOGAN_PACIFYCOOLSNOW"] = "Pacificación de la Región: Paso Montañoso"
lang["#MISSION_LOGAN_PACIFYCOOLSNOW_DESC"] = "Hay más amenazas en el Paso de la Montaña que solo los Ice Picks; la vida silvestre junto con la Compañía Cipher son grandes amenazas para la estabilidad de la región."
lang["#MISSION_LOGAN_PACIFYCOOLSNOW_HINT"] = "Encuentra y elimina a los jefes de yao guai, mirelurk y Cipher en el Paso de la Montaña."
lang["#MISSION_LOGAN_PACIFYCOOLSNOW_COMPLETE"] = "Con las principales amenazas de la región eliminadas, el Campamento Willow prosperará. Sin embargo, debemos permanecer vigilantes ya que pueden regresar rápidamente."

lang["#MISSION_LOGAN_PACIFYAPOC"] = "Pacificación de la Región: Tierras de Cenizas"
lang["#MISSION_LOGAN_PACIFYAPOC_DESC"] = "No llegaremos a ningún lado si gastamos todo nuestro tiempo y recursos atacando a los soldados rasos, necesitamos ir tras los jefes de la región de las Tierras de Cenizas."
lang["#MISSION_LOGAN_PACIFYAPOC_HINT"] = "Encuentra y elimina a todos los jefes en las Tierras de Ceniza."
lang["#MISSION_LOGAN_PACIFYAPOC_COMPLETE"] = "Con los jefes de la región muertos, quizás los rangers de la casa segura puedan respirar tranquilos. Aunque esa región sigue siendo inhóspita y peligrosa."

lang["#MISSION_LOGAN_PACIFYKNEEDEEP"] = "Pacificación de la Región: Estuario Muerto"
lang["#MISSION_LOGAN_PACIFYKNEEDEEP_DESC"] = "Según los informes, hay una región en el norte que contiene valiosos recursos naturales y materiales, junto con instalaciones de antes de la guerra. Sin embargo, es el hogar de vida silvestre peligrosa y contrabandistas. Despeja la región para que pueda ser utilizada."
lang["#MISSION_LOGAN_PACIFYKNEEDEEP_HINT"] = "Encuentra y elimina a pejesapos, mirelurks, crocogarras, contrabandistas y al jefe en el Estuario Muerto."
lang["#MISSION_LOGAN_PACIFYKNEEDEEP_COMPLETE"] = "Ahora que se puede entrar en la región, los recursos estarán disponibles para nosotros. Gran trabajo como siempre $playername."

lang["#MISSION_LOGAN_PACIFYSALEM"] = "Pacificación de la Región: Salem"
lang["#MISSION_LOGAN_PACIFYSALEM_DESC"] = "Según los informes, se dice que hay una región urbana diezmada que contiene refugiados rodeados por una lucha de poder por la región. Ayuda a resolver esta lucha eliminando a los bandidos y las fuerzas mutantes."
lang["#MISSION_LOGAN_PACIFYSALEM_HINT"] = "Encuentra y elimina a los Shadowed y a la Unidad en Salem."
lang["#MISSION_LOGAN_PACIFYSALEM_COMPLETE"] = "Ahora que dos de los grupos en Salem han sufrido grandes pérdidas, los refugiados deberían poder encontrar algo de estabilidad."

lang["#MISSION_LOGAN_WINFORTHEBEAR"] = "Otra Victoria para el Oso"
lang["#MISSION_LOGAN_WINFORTHEBEAR_DESC"] = "Con todas tus contribuciones, tengo una oportunidad única en la vida. Una escopeta antidisturbios de antes de la guerra, todo lo que necesito de ti son algunos materiales y será toda tuya."
lang["#MISSION_LOGAN_WINFORTHEBEAR_HINT"] = "Los materiales avanzados rara vez se encuentran en todo el yermo. Algunos accesorios para la escopeta antidisturbios se podrán comprar después de completar esta misión."
lang["#MISSION_LOGAN_WINFORTHEBEAR_COMPLETE"] = "$playername, no me queda nada más para ti. Si pudiera darte una medalla, lo haría. Protegiste tú solo Salt Wells y sus regiones circundantes."

lang["#MISSION_LOGAN_RIOTSUPPRESSION"] = "Supresión de Disturbios"
lang["#MISSION_LOGAN_RIOTSUPPRESSION_DESC"] = "¿Te interesa una vuelta de la victoria? Qué tal si pruebas esa escopeta antidisturbios."
lang["#MISSION_LOGAN_RIOTSUPPRESSION_HINT"] = "Encuentra y elimina a 300 enemigos usando una Escopeta Antidisturbios."
lang["#MISSION_LOGAN_RIOTSUPPRESSION_COMPLETE"] = "Como se esperaba de ti $playername, impecable como siempre."

RELOADSCHEMA = true
